INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(50011, 'Genesis 24:46', 'Genesis', 24, 46, 'هغې زر خپل منګی د اوږو څخه راښکته کړ او ویې ویل: ‹وڅښه. زه به ستا اوښانو ته هم اوبه ورکړم.› نو بیا ما وڅښلې او هغې اوښانو ته هم اوبه ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_46.mp3', '', 1761754199, 1761754199),
(50012, 'Genesis 24:47', 'Genesis', 24, 47, 'د هغې څخه مې پوښتنه وکړه: ‹ته د چا لور یې؟› نو هغې وویل: ‹زه د بتوییل لور یم او د ناحور او میلکه لمسۍ یم.› نو د هغې په پوزه کې مې پېزوان واچاوه او په لاسونو کې مې ورته کړۍ‌ګانې واچولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_47.mp3', '', 1761754199, 1761754199),
(50013, 'Genesis 24:48', 'Genesis', 24, 48, 'ما سجده وکړه او د څښتن عبادت مې وکړ او د خپل بادار ابراهیم څښتن خدای مې وستایه چې ماته یې سمه لاره وښودله چې د خپل بادار د ورور لمسۍ د هغه زوی ته وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_48.mp3', '', 1761754199, 1761754199),
(50014, 'Genesis 24:49', 'Genesis', 24, 49, 'نو اوس که چېرې زما د بادار سره وفاداري او تلپاتې مینه کوې هم راته ووایه او که نه یې کوې هم ماته ووایه، ترڅو زه پرېکړه وکړم چې بل چېرته لاړ شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_49.mp3', '', 1761754199, 1761754199),
(50015, 'Genesis 24:50', 'Genesis', 24, 50, 'لابان او بتوییل ځواب ورکړ: «څرنګه چې دا خبره د څښتن له خوا ده، نو مونږ په دې هکله پرېکړه نه شو کولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_50.mp3', '', 1761754199, 1761754199),
(50016, 'Genesis 24:51', 'Genesis', 24, 51, 'دا دی ربکا حاضره ده هغه درسره واخله او ځه. لکه څنګه چې څښتن په خپله ویلي دي، هغه دې ستا د بادار د زوی ښځه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_51.mp3', '', 1761754199, 1761754199),
(50017, 'Genesis 24:52', 'Genesis', 24, 52, 'څنګه چې د ابراهیم ناظر دا خبره واورېدله، نو سجده یې وکړه او د څښتن عبادت یې وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_52.mp3', '', 1761754199, 1761754199),
(50018, 'Genesis 24:53', 'Genesis', 24, 53, 'بیا ناظر کالي، د سپینو زرو او سرو زرو ګاڼې راوویستل او ربکا ته یې ورکړل او د هغې ورور او مور ته یې هم قیمتي سوغاتونه ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_53.mp3', '', 1761754199, 1761754199),
(50019, 'Genesis 24:54', 'Genesis', 24, 54, 'بیا د ابراهیم ناظر او د هغه کسانو وخوړل او وڅښل او شپه یې هلته تېره کړه. کله چې هغوی سهار پاڅېدل، ناظر وویل: «ما رخصت کړه چې بېرته خپل بادار ته لاړ شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_54.mp3', '', 1761754199, 1761754199),
(50020, 'Genesis 24:55', 'Genesis', 24, 55, 'خو د ربکا ورور او مور وویل: «انجلۍ دې یوه هفته یا لس ورځې زمونږ سره پاتې شي، بیا تاسو کولای شئ چې لاړ شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_55.mp3', '', 1761754199, 1761754199),
(50021, 'Genesis 24:56', 'Genesis', 24, 56, 'خو هغه وویل: «مونږ مه ایساروئ. څښتن زما سفر بریالی کړی دی، پرېږدئ چې بېرته خپل بادار ته لاړ شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_56.mp3', '', 1761754199, 1761754199),
(50022, 'Genesis 24:57', 'Genesis', 24, 57, 'هغوی وویل: «راځئ چې انجلۍ راوغواړو او په دې هکله د هغې څخه پوښتنه وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_57.mp3', '', 1761754199, 1761754199),
(50023, 'Genesis 24:58', 'Genesis', 24, 58, 'نو هغوی ربکا راوغوښتله او پوښتنه یې ترې وکړه: «ایا د دې سړي سره ځې؟» هغې وویل: «هو، ځم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_58.mp3', '', 1761754199, 1761754199),
(50024, 'Genesis 24:59', 'Genesis', 24, 59, 'نو هغوی خپله خور ربکا او د هغې زړه نوکره د ابراهیم د ناظر او د هغه د کسانو سره ولېږلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_59.mp3', '', 1761754199, 1761754199),
(50025, 'Genesis 24:60', 'Genesis', 24, 60, 'هغوی د ربکا دپاره برکت وغوښت او ورته یې وویل: ای زمونږ خورې! ته دې شې مور د میلیونونو اولادونو فتح دې کړي ښارونه ستا اولاده د دښمنانو خپلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_60.mp3', '', 1761754199, 1761754199),
(50026, 'Genesis 24:61', 'Genesis', 24, 61, 'بیا ربکا او د هغې وینځې تیارې شوې او په اوښانو باندې سپرې شوې او د سړي سره روانې شوې. نو ناظر ربکا د ځان سره واخیستله او لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_61.mp3', '', 1761754199, 1761754199),
(50027, 'Genesis 24:62', 'Genesis', 24, 62, 'په دې وخت کې اسحاق د بئرلحي ریي څخه راغلی ؤ او د کنعان په جنوب کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_62.mp3', '', 1761754199, 1761754199),
(50028, 'Genesis 24:63', 'Genesis', 24, 63, 'یو ماښام اسحاق په پټیو کې چکر واهه. څنګه چې هغه خپلې سترګې پورته کړې ویې لیدل چې اوښان راروان دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_63.mp3', '', 1761754199, 1761754199),
(50029, 'Genesis 24:64', 'Genesis', 24, 64, 'ربکا هم خپلې سترګې پورته کړې او اسحاق یې ولیده، نو د اوښ څخه راښکته شوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_64.mp3', '', 1761754199, 1761754199),
(50030, 'Genesis 24:65', 'Genesis', 24, 65, 'او د ناظر څخه یې پوښتنه وکړه: «هغه سړی څوک دی چې په پټي کې زمونږ خوا ته راروان دی؟» ناظر ځواب ورکړ: «هغه زما بادار دی.» نو هغې خپل څادر راواخیست او خپل ځان یې ورباندې پټ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_65.mp3', '', 1761754199, 1761754199),
(50031, 'Genesis 24:66', 'Genesis', 24, 66, 'کوم کارونه چې ناظر کړي وو، هغه ټول یې اسحاق ته بیان کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_66.mp3', '', 1761754199, 1761754199),
(50032, 'Genesis 24:67', 'Genesis', 24, 67, 'اسحاق ربکا د خپلې مور ساره خېمې ته راوستله او د هغې سره یې واده وکړ. نو ربکا د هغه ښځه شوه او د هغې سره یې مینه کوله او اسحاق د خپلې مور د مړینې څخه وروسته تسلي وموندله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis24_verse_67.mp3', '', 1761754199, 1761754199),
(50033, 'Ruth 3:1', 'Ruth', 3, 1, 'څه موده وروسته نعومي روت ته وویل: «ای زما لورې زه باید ستا دپاره مېړه پیدا کړم، هغه به تاته کور درکړي او په تا به پام کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_1.mp3', '', 1761754199, 1761754199),
(50034, 'Ruth 3:2', 'Ruth', 3, 2, 'ته پوهېږې چې بوعز زمونږ خپلوان دی او تا د هغو ښځو سره وږي راټول کړي دي چې د هغه دپاره کار کوي. ګوره، نن شپه به هغه په درمند باندې اوربشې بادوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_2.mp3', '', 1761754199, 1761754199),
(50035, 'Ruth 3:3', 'Ruth', 3, 3, 'اوس ولامبه او لږ عطر په ځان واچوه، بیا خپلې ښې جامې واغونده او درمند ته لاړه شه. خو ترڅو پورې چې هغه د خوراک او څښاک څخه وزګار شوی نه وي، خپل ځان مه ورښکاره کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_3.mp3', '', 1761754199, 1761754199),
(50036, 'Ruth 3:4', 'Ruth', 3, 4, 'وګوره چې هغه چېرته څملي، بیا کله چې هغه ویده شي، پښې یې لوڅې کړه او د هغه د پښو سره پرېوځه. بیا به هغه تاته ووایي چې څه وکړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_4.mp3', '', 1761754199, 1761754199),
(50037, 'Ruth 3:5', 'Ruth', 3, 5, 'روت په ځواب کې وویل: «څه چې ته وایې هماغسې به وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_5.mp3', '', 1761754199, 1761754199),
(50038, 'Ruth 3:6', 'Ruth', 3, 6, 'نو روت درمند ته لاړه او هماغسې یې وکړل لکه څنګه چې خواښې یې ورته ویلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_6.mp3', '', 1761754199, 1761754199),
(50039, 'Ruth 3:7', 'Ruth', 3, 7, 'وروسته له خوړلو او څښلو نه بوعز د خوشحالۍ احساس کاوه، هغه لاړ او د غلو دانو د ډېرۍ تر څنګ ویده شو. روت غلې غلې ورنژدې شوه، هغې د بوعز پښې لوڅې کړې او د هغه د پښو سره پرېوتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_7.mp3', '', 1761754199, 1761754199),
(50040, 'Ruth 3:8', 'Ruth', 3, 8, 'د نیمې شپې په شاوخوا کې، بوعز ناڅاپه راویښ شو او ډېر حیران شو چې خپلو پښو سره یې ښځه ولیدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_8.mp3', '', 1761754199, 1761754199),
(50041, 'Ruth 3:9', 'Ruth', 3, 9, 'هغه پوښتنه وکړه: «ته څوک یې؟» هغې په ځواب کې وویل: «ښاغلیه، زه روت یم ستا د پښو خاورې. ته زما هغه خپلوان یې چې په ما پام وکړې، نو ته ما سره واده وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_9.mp3', '', 1761754199, 1761754199),
(50042, 'Ruth 3:10', 'Ruth', 3, 10, 'بوعز په ځواب کې وویل: «څښتن دې تاته برکت درکړي! ته اوس د خپلې خواښې سره د ټولې مرستې څخه هم لا زیاته وفاداري ښایې. تا کولای شول چې د ځان دپاره دې یو ځوان شتمن یا غریب سړی لټولای وای، خو تا داسې ونه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_10.mp3', '', 1761754199, 1761754199),
(50043, 'Ruth 3:11', 'Ruth', 3, 11, 'اوس فکر مه کوه، زه به همداسې وکړم څنګه چې ته غواړې. په ښار کې ټول ستا درناوی کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_11.mp3', '', 1761754199, 1761754199),
(50044, 'Ruth 3:12', 'Ruth', 3, 12, 'دا رښتیا ده چې زه ستا نژدې خپلوان یم چې باید درباندې پام وکړم. خو بل څوک هم شته چې هغه ستا ډېر نژدې خپلوان دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_12.mp3', '', 1761754199, 1761754199),
(50045, 'Ruth 3:13', 'Ruth', 3, 13, 'تر سهاره پورې دلته پاتې شه، بیا به زه ځان پوه کړم که چېرې هغه راضي شي چې ستا مسوولیت په غاړه اخلي، نو ښه به وي. که هغه راضي نه شو، نو زه د ژوندي څښتن په نوم قسم خورم چې زه به په خپله ستا مسوولیت په غاړه واخلم. اوس څمله او تر سهاره پورې پاتې شه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_13.mp3', '', 1761754199, 1761754199),
(50046, 'Ruth 3:14', 'Ruth', 3, 14, 'روت بیا پرېوتله، خو هغه د رڼا کېدلو نه مخکې راویښه شوه، ځکه بوعز نه غوښتل چې بل څوک پوه شي چې روت هلته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_14.mp3', '', 1761754199, 1761754199),
(50047, 'Ruth 3:15', 'Ruth', 3, 15, 'بیا بوعز ورته وویل: «خپله چپنه خوره کړه» او هغه په کې شاوخوا شل کیلو ګرامه غلې دانې ورواچولې او د هغې په اوږه باندې یې کېښودله. روت بېرته ښار ته راغله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_15.mp3', '', 1761754199, 1761754199),
(50048, 'Ruth 3:16', 'Ruth', 3, 16, 'او چې کله کور ته راورسېدله، نو خواښې ورڅخه پوښتنه وکړه چې «لورې، څه وشو؟» روت ورته ټول هغه څه وویل چې بوعز د هغې دپاره کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_16.mp3', '', 1761754199, 1761754199),
(50049, 'Ruth 3:17', 'Ruth', 3, 17, 'هغې زیاته کړه: «بوعز ماته وویل چې زه باید تاته تش لاس رانه شم، نو همدا ؤ چې ماته یې دا ټولې اوربشې راکړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_17.mp3', '', 1761754199, 1761754199),
(50050, 'Ruth 3:18', 'Ruth', 3, 18, 'نعومي روت ته وویل: «زما لورې اوس صبر کوه، ترڅو معلومه شي چې څه پېښیږي. بوعز به نن تر هغې ارام ونه کړي، ترڅو یې چې دا موضوع نه وي حل کړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth3_verse_18.mp3', '', 1761754199, 1761754199),
(50051, 'Ezekiel 48:8', 'Ezekiel', 48, 8, 'د یهودا د برخې په جنوب کې دې د ځمکې یوه بله برخه وي چې د یو ځانګړي مقصد دپاره بېله کړای شي. هغه دې د شمال نه د جنوب خواته دولس نیم کیلومتره سور ولري او اوږدوالی به یې د ختیځ نه لوېدیځ خواته د قبیلو د برخو سره برابره وي. عبادتځای به د دې ساحې په دننه کې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_8.mp3', '', 1761754199, 1761754199),
(50052, 'Ezekiel 48:9', 'Ezekiel', 48, 9, 'د دې برخې په منځنۍ ځمکه کې به څښتن ته یوه وقف شوې ځانګړې ساحه وي چې هغه به دولس نیم کیلومتره اوږدوالی او لس کیلومتره سور ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_9.mp3', '', 1761754199, 1761754199),
(50053, 'Ezekiel 48:10', 'Ezekiel', 48, 10, 'کاهنانو ته به په دې سپېڅلې ساحه کې برخه ورکول کیږي. د ختیځ نه لوېدیځ خواته به د هغوی برخه دولس نیم کیلومتره او د شمال نه تر جنوب پورې پنځه کیلومتره وي. د څښتن عبادتځای به د دې ساحې په دننه کې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_10.mp3', '', 1761754199, 1761754199),
(50054, 'Ezekiel 48:11', 'Ezekiel', 48, 11, 'دا سپېڅلې ساحه به د هغو کاهنانو وي چې د صادوق اولاده ده. هغوی په وفادارۍ سره زما خدمت کړی ؤ او هغوی د نورو اسراییلیانو سره په غلطو کارونو کې ملګري نه شول، لکه څنګه چې د لاویانو قبیلې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_11.mp3', '', 1761754199, 1761754199),
(50055, 'Ezekiel 48:12', 'Ezekiel', 48, 12, 'نو هغوی ته به د لاویانو د ساحې په څنګ کې یوه ځانګړې ساحه ورکول کیږي او هغه به د ټولو نه زیاته سپېڅلې ساحه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_12.mp3', '', 1761754199, 1761754199),
(50056, 'Ezekiel 48:13', 'Ezekiel', 48, 13, 'لاویان به هم یوه ځانګړې ساحه ولري چې د کاهنانو د ساحې په څنګ کې به وي. دا به هم د ختیځ نه لوېدیځ خواته دولس نیم کیلومتره اوږدوالی او د شمال نه تر جنوب پورې به پنځه کیلومتره سور ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_13.mp3', '', 1761754199, 1761754199),
(50057, 'Ezekiel 48:14', 'Ezekiel', 48, 14, 'کومه ساحه چې څښتن ته وقف کیږي، هغه د ټولو ځمکو نه ډېره ښه ځمکه ده او د دې ځمکې نه به یوه ټوټه هم نه خرڅیږي، نه به بدلیږي او نه به کوم بل چاته لېږدول کیږي. ځکه چې دا ځمکه سپېڅلې ده او د څښتن ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_14.mp3', '', 1761754199, 1761754199),
(50058, 'Ezekiel 48:15', 'Ezekiel', 48, 15, 'د ځانګړې ساحې کومه برخه چې پاتې ده، هغه دولس نیم کیلومتره اوږدوالی او دوه نیم کیلومتره سور لري. هغه سپېڅلې نه ده، خو هغه به د عامو خلکو د اړتیا دپاره یعنې د ښار، کورونو او د خالي ځمکو دپاره وي. ښار باید په هغې ساحه کې وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_15.mp3', '', 1761754199, 1761754199),
(50059, 'Ezekiel 48:16', 'Ezekiel', 48, 16, 'دا ساحه به د مربع په شکل وي او هره څنډه به یې دوه زره او دوه سوه پنځوس متره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_16.mp3', '', 1761754199, 1761754199),
(50060, 'Ezekiel 48:17', 'Ezekiel', 48, 17, 'د ښار ګردچاپېره هرې خواته به یوسلو پنځه ویشت متره خالي ځمکه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_17.mp3', '', 1761754199, 1761754199),
(50061, 'Ezekiel 48:18', 'Ezekiel', 48, 18, 'نوره ځمکه به په دوو برخو کې د ختیځ او لوېدیځ خواته پنځه کیلومتره اوږدوالی او دوه نیم کیلومتره سور ولري. دا ځمکه به د ښار د کار‌کوونکو دپاره خواړه برابروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_18.mp3', '', 1761754199, 1761754199),
(50062, 'Ezekiel 48:19', 'Ezekiel', 48, 19, 'هغه کار‌کوونکي چې په ښار کې اوسیږي، هغه که د هرې قبیلې څخه وي، کولای شي چې دا ځمکه وکري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_19.mp3', '', 1761754199, 1761754199),
(50063, 'Ezekiel 48:20', 'Ezekiel', 48, 20, 'نو د ځمکې ټوله جلا شوې برخه چې په هغې کې سپېڅلې ساحه او ښار شامل دي، هره څنډه به یې دولس نیم کیلومتره مربع وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_20.mp3', '', 1761754199, 1761754199),
(50064, 'Ezekiel 48:28', 'Ezekiel', 48, 28, 'د جاد د برخې جنوبي سرحد به د تامار نه د لوېدیځ خواته د مریبوت‌قادش تر چینو پورې او د هغه ځای نه شمال لوېدیځ خواته د مصر د خوړ په اوږدو کې د مدیترانې تر بحیرې پورې ورسیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_28.mp3', '', 1761754199, 1761754199),
(50065, 'Ezekiel 48:29', 'Ezekiel', 48, 29, 'څښتن تعالی داسې وایي: «په دې ډول به دا ځمکه د اسراییلو په قبیلو باندې د ملکیت په ډول په برخو وېشل کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_29.mp3', '', 1761754199, 1761754199),
(50066, 'Ezekiel 48:35', 'Ezekiel', 48, 35, 'د ښار د څلورو خواو اوږدوالی به نهه کیلومتره وي. د ښار نوم به د دې ورځې نه ورسته دا وي: «څښتن دلته دی!»»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel48_verse_35.mp3', '', 1761754199, 1761754199),
(50067, 'Genesis 13:1', 'Genesis', 13, 1, 'ابرام د خپلې ښځې او خپلو ټولو شیانو سره چې درلودل یې د مصر څخه د کنعان جنوبي خواته لاړ او لوط د هغه سره لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_1.mp3', '', 1761754199, 1761754199),
(50068, 'Genesis 13:2', 'Genesis', 13, 2, 'ابرام شتمن سړی ؤ او هغه ډېر حیوانات، سره زر او سپین زر درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_2.mp3', '', 1761754199, 1761754199),
(50069, 'Genesis 13:3', 'Genesis', 13, 3, 'هغه یو ځای او بل ځای ګرځېده او د بیت‌ییل خوا ته لاړ او هغه ځای ته ورسېده چې د بیت‌ییل او عای ترمنځ پروت دی او ابرام پخوا هلته خپلې خېمې ودرولې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_3.mp3', '', 1761754199, 1761754199),
(50070, 'Genesis 13:4', 'Genesis', 13, 4, 'چېرته چې هغه د قربانۍ ځای جوړ کړی ؤ، هلته هغه د څښتن عبادت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_4.mp3', '', 1761754199, 1761754199),
(50071, 'Genesis 13:5', 'Genesis', 13, 5, 'لوط هم چې د ابرام سره ؤ، رمې او پادې او خېمې درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_5.mp3', '', 1761754199, 1761754199),
(50072, 'Genesis 13:6', 'Genesis', 13, 6, 'په دې خاطر چې هغوی دواړو ډېر زیات حیوانات درلودل او د هغوی دپاره په پوره اندازه د څړځایونه نه وو، نو دوی نه شو کولای چې دواړه یوځای سره واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_6.mp3', '', 1761754199, 1761754199),
(50073, 'Genesis 13:7', 'Genesis', 13, 7, 'نو د ابرام او لوط د شپنو ترمنځ شخړه رامنځته شوه. په هغه وخت کې کنعانیان او فرزیان هم په دې خاوره کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_7.mp3', '', 1761754199, 1761754199),
(50074, 'Genesis 13:8', 'Genesis', 13, 8, 'نو ابرام لوط ته وویل: «زما او ستا، یا زما د شپنو او ستا د شپنو ترمنځ باید شخړه نه وي، ځکه چې مونږ سره خپلوان یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_8.mp3', '', 1761754199, 1761754199),
(50075, 'Genesis 13:9', 'Genesis', 13, 9, 'نو بیا راځئ چې سره بېل شو. د ځمکې هره برخه چې ته غواړې هغه غوره کړه. ته یو خوا لاړ شه او زه به بلې خواته لاړ شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_9.mp3', '', 1761754199, 1761754199),
(50076, 'Genesis 13:10', 'Genesis', 13, 10, 'لوط شاوخوا ته وکتل او د اردن ټوله دره یې ولیدله چې د سوغر پورې لکه د څښتن د باغ او مصر په شان شنه وه. دا هغه وخت ؤ چې څښتن لا سدوم او عموره له منځه نه وو وړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_10.mp3', '', 1761754199, 1761754199),
(50077, 'Genesis 13:11', 'Genesis', 13, 11, 'نو لوط د اردن ټوله دره د خپل ځان دپاره خوښه کړه او د لمرخاته خواته یې کډه وکړه. په دې ډول هغوی یو د بل څخه بېل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_11.mp3', '', 1761754199, 1761754199),
(50078, 'Genesis 13:12', 'Genesis', 13, 12, 'ابرام د کنعان په خاوره کې پاتې شو او لوط د هغو ښارونو په منځ کې چې په دره کې پراته وو، ځای په ځای شو او سدوم ته نژدې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_12.mp3', '', 1761754199, 1761754199),
(50079, 'Genesis 13:13', 'Genesis', 13, 13, 'د سدوم خلک ډېر بدکاره وو او د څښتن په وړاندې یې ډېر سخت ګناهونه کول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_13.mp3', '', 1761754199, 1761754199),
(50080, 'Genesis 13:14', 'Genesis', 13, 14, 'د ابرام څخه د لوط له بېلېدلو وروسته څښتن ابرام ته وویل: «اوس دې خپلې سترګې پورته کړه او د هغه ځای څخه چې ته په کې یې، شمال، جنوب، لمرخاته او لمرپرېواته خواته وګوره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_14.mp3', '', 1761754199, 1761754199),
(50081, 'Genesis 13:15', 'Genesis', 13, 15, 'دا ټوله ځمکه چې ته یې وینې زه به یې تا او ستا اولادې ته درکړم او دا به تر ابده پورې ستاسو وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_15.mp3', '', 1761754199, 1761754199),
(50082, 'Genesis 13:16', 'Genesis', 13, 16, 'زه به دومره زیاته اولاده درکړم چې د دښتې د شګو په شان وي چې څوک یې نه شي شمارلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_16.mp3', '', 1761754199, 1761754199),
(50083, 'Genesis 13:17', 'Genesis', 13, 17, 'اوس لاړ شه او ټول هېواد وګوره، ځکه چې هغه ټول تاته درکوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_17.mp3', '', 1761754199, 1761754199),
(50084, 'Genesis 13:18', 'Genesis', 13, 18, 'نو ابرام خپلې خېمې واخیستلې او د ممري لویو ونو ته نژدې چې په حبرون کې دي ځای په ځای شو او په هغه ځای کې یې د څښتن دپاره د قربانۍ ځای جوړ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis13_verse_18.mp3', '', 1761754199, 1761754199),
(50085, 'Genesis 41:1', 'Genesis', 41, 1, 'پوره دوه کاله تېر شوي وو چې فرعون خوب ولیده چې د نیل د سیند په غاړه ولاړ ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_1.mp3', '', 1761754199, 1761754199),
(50086, 'Genesis 41:2', 'Genesis', 41, 2, 'ناڅاپه اووه ښې او چاغې غواګانې د سیند څخه راووتلې او په لوخو کې څرېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_2.mp3', '', 1761754199, 1761754199),
(50087, 'Genesis 41:3', 'Genesis', 41, 3, 'د هغو څخه وروسته نورې اووه غواګانې چې بدرنګې او ډنګرې وې، راووتلې او د سیند په غاړه د هغو تر‌څنګه ودرېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_3.mp3', '', 1761754199, 1761754199),
(50088, 'Genesis 41:4', 'Genesis', 41, 4, 'بدرنګو او ډنګرو غواګانو هغه ښې او چاغې غواګانې وخوړلې. بیا فرعون راویښ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_4.mp3', '', 1761754199, 1761754199),
(50089, 'Genesis 41:5', 'Genesis', 41, 5, 'هغه بیا ویده شو او بل خوب یې ولیده چې د غلو دانو اووه ډک او پاخه وږي په یوه ډنډر کې راشنه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_5.mp3', '', 1761754199, 1761754199),
(50090, 'Genesis 41:6', 'Genesis', 41, 6, 'له هغو څخه وروسته د غلو دانو نور اووه نري او د دښتې باد سوځولي وږي راشنه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_6.mp3', '', 1761754199, 1761754199),
(50091, 'Genesis 41:7', 'Genesis', 41, 7, 'د غلو دانو اوو نریو وږو هغه ډک او پاخه وږي روغ تېر کړل. بیا فرعون راویښ شو او پوه شو چې هغه خوب لیدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_7.mp3', '', 1761754199, 1761754199),
(50092, 'Genesis 41:8', 'Genesis', 41, 8, 'په سهار کې د هغه فکر پرېشانه ؤ. هغه د مصر ټول جادوګران او حکیمان راوغوښتل. هغه خپل خوبونه هغوی ته بیان کړل، خو هېڅ یو ونه شو کولای چې هغه فرعون ته تعبیر کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_8.mp3', '', 1761754199, 1761754199),
(50093, 'Genesis 41:9', 'Genesis', 41, 9, 'په دې وخت کې د ساقیانو مشر فرعون ته وویل: «نن راته رایاد شول چې زما څخه خطا شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_9.mp3', '', 1761754199, 1761754199),
(50094, 'Genesis 41:10', 'Genesis', 41, 10, 'یوځل فرعون په خپلو نوکرانو باندې په قهر شوی ؤ او زه او د نانوایانو مشر یې د دربار د ساتونکو د قوماندان په کور کې په زندان کې واچولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_10.mp3', '', 1761754199, 1761754199),
(50095, 'Genesis 41:11', 'Genesis', 41, 11, 'مونږ دواړو په یوه شپه خوب ولیده او هر یو خوب ځانته خپله معنی درلودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_11.mp3', '', 1761754199, 1761754199),
(50096, 'Genesis 41:12', 'Genesis', 41, 12, 'په هغه ځای کې یو عبرانی ځوان چې د دربار د ساتونکو د قوماندان غلام ؤ، زمونږ سره ؤ. مونږ خپل خوبونه هغه ته بیان کړل او هغه زمونږ خوبونه زمونږ دپاره تعبیر کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_12.mp3', '', 1761754199, 1761754199),
(50097, 'Genesis 41:13', 'Genesis', 41, 13, 'لکه څنګه چې هغه تعبیر کړی ؤ، کټ مټ هماغسې وشول. زه بېرته په خپل ځای مقرر شوم او هغه بل سړی په دار وځړول شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_13.mp3', '', 1761754199, 1761754199),
(50098, 'Genesis 41:14', 'Genesis', 41, 14, 'نو فرعون یوسف راوغوښت او هغه یې ډېر زر د زندان څخه راوویست. یوسف خپل سر او ږیره وخرایله، خپل کالي یې بدل کړل او د فرعون حضور ته راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_14.mp3', '', 1761754199, 1761754199),
(50099, 'Genesis 41:15', 'Genesis', 41, 15, 'فرعون یوسف ته وویل: «ما خوب لیدلی او څوک نشته چې هغه تعبیر کړي. خو ما ستا په هکله اورېدلي دي چې کله خوب واورې، نو تعبیر یې کولای شې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_15.mp3', '', 1761754199, 1761754199),
(50100, 'Genesis 41:16', 'Genesis', 41, 16, 'یوسف فرعون ته په ځواب کې وویل: «اعلیحضرته، زه یې نه شم کولای، خو خدای به ښه تعبیر درکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_16.mp3', '', 1761754199, 1761754199),
(50101, 'Genesis 41:17', 'Genesis', 41, 17, 'فرعون یوسف ته وویل: «ما خوب ولیده چې زه د نیل د سیند په غاړه ولاړ وم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_17.mp3', '', 1761754199, 1761754199),
(50102, 'Genesis 41:18', 'Genesis', 41, 18, 'په دې وخت کې اووه چاغې او ښې غواګانې د سیند څخه راووتلې او په لوخو کې څرېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_18.mp3', '', 1761754199, 1761754199),
(50103, 'Genesis 41:19', 'Genesis', 41, 19, 'د هغوی څخه وروسته نورې اووه غواګانې راووتلې چې داسې ډنګرې او بدشکله وې چې ما د مصر په ټول هېواد کې هېڅکله نه وې لیدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_19.mp3', '', 1761754199, 1761754199),
(50104, 'Genesis 41:20', 'Genesis', 41, 20, 'ډنګرو او بدشکله غواګانو هغه لومړنۍ چاغې غواګانې وخوړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_20.mp3', '', 1761754199, 1761754199),
(50105, 'Genesis 41:21', 'Genesis', 41, 21, 'خو د خوړلو څخه وروسته هم څوک نه پوهېدل چې دوی به څه خوړلي وي، ځکه چې هغوی د پخوا په شان ډنګرې ښکاره کېدلې. نو په دې وخت کې زه راویښ شوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_21.mp3', '', 1761754199, 1761754199),
(50106, 'Genesis 41:22', 'Genesis', 41, 22, 'همدارنګه ما په خوب کې ولیدل چې د غلو دانو اووه ډک او پاخه وږي په یوه ډنډر کې راشنه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_22.mp3', '', 1761754199, 1761754199),
(50107, 'Genesis 41:23', 'Genesis', 41, 23, 'د هغو څخه وروسته نور اووه نري او د دښتې باد سوځولي وږي راشنه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_23.mp3', '', 1761754199, 1761754199),
(50108, 'Genesis 41:24', 'Genesis', 41, 24, 'اووه نریو وږو هغه ډک وږي روغ تېر کړل. نو ما خپل خوب جادوګرانو ته وویل، خو هېچا ونه شو کولای چې هغه ماته تعبیر کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_24.mp3', '', 1761754199, 1761754199),
(50109, 'Genesis 41:25', 'Genesis', 41, 25, 'نو یوسف فرعون ته وویل: «د دواړو خوبونو معنی یوه ده. څه چې خدای غواړي ویې کړي، هغه یې تاسو ته څرګند کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_25.mp3', '', 1761754199, 1761754199),
(50110, 'Genesis 41:26', 'Genesis', 41, 26, 'اووه ښې غواګانې اووه کاله دي او د غلو دانو اووه ډک وږي هم اووه کاله دي، هغوی یوشان معنی لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_26.mp3', '', 1761754199, 1761754199);